(async function () {
    const hostWindow = window.parent;
    const DB_NAME = "LocalDreamSD_DB", STORE_NAME = "images";
    const DEFAULT_CONFIG = {
        api_host: "127.0.0.1",
        api_port: "8000",
        model_id: "",
        resolution: 512,
        scheduler_base: "dpm",
        use_karras: false,
        steps: 20,
        cfg: 7.0,
        denoise_strength: 60,
        seed: "",
        negative_prompt: "low quality, bad anatomy, ugly, deformed, distorted, blurry, noisy, artifacts, lowres, watermark",
        theme: "dark",
        fab_enabled: false,
        gallery_view: "grid",
        auto_clear: false,
        keep_floors: 10
    };
    function getConfig() { const conf = localStorage.getItem("LDSD_Config"); return conf ? { ...DEFAULT_CONFIG, ...JSON.parse(conf) } : DEFAULT_CONFIG; }
    function saveConfig(updates) { const conf = { ...getConfig(), ...updates }; localStorage.setItem("LDSD_Config", JSON.stringify(conf)); return conf; }
    function getApiBase() { const c = getConfig(); return 'http://' + c.api_host + ':' + c.api_port; }
    function hashPrompt(str) { let hash = 0; for (let i = 0; i < str.length; i++) hash = ((hash << 5) - hash) + str.charCodeAt(i) | 0; return 'ld_' + Math.abs(hash).toString(16); }
    let isApiOnline = false, isProcessing = false, manualProgressCallback = null, availableModels = [];
    async function checkApiStatus() {
        if (isProcessing) return;
        try {
            const controller = new AbortController(); setTimeout(() => controller.abort(), 2000);
            const res = await fetch(getApiBase() + '/api/models/loaded', { signal: controller.signal });
            if (res.ok) { isApiOnline = true; }
            else { isApiOnline = false; }
        } catch (e) { isApiOnline = false; }
        const dot = hostWindow.document.getElementById('ldsd-ui-dot');
        if (dot) dot.style.background = isApiOnline ? '#22c55e' : '#ef4444';
    }
    setInterval(checkApiStatus, 5000);
    checkApiStatus();
    const BlobUrlCache = {};
    const dbPromise = new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME);
        request.onupgradeneeded = (e) => { const db = e.target.result; if (!db.objectStoreNames.contains(STORE_NAME)) db.createObjectStore(STORE_NAME, { keyPath: 'hash' }); };
        request.onsuccess = (e) => { const db = e.target.result; if (db.objectStoreNames.contains(STORE_NAME)) resolve(db); else { const upgradeReq = indexedDB.open(DB_NAME, db.version + 1); upgradeReq.onupgradeneeded = (e2) => { const upgradeDb = e2.target.result; if (!upgradeDb.objectStoreNames.contains(STORE_NAME)) upgradeDb.createObjectStore(STORE_NAME, { keyPath: 'hash' }); }; upgradeReq.onsuccess = (e2) => resolve(e2.target.result); upgradeReq.onerror = () => reject(upgradeReq.error); } };
        request.onerror = () => reject(request.error);
    });
    async function saveImageToDB(hash, blob, prompt, config, msgId, actualSeed) {
        const db = await dbPromise;
        return new Promise((res, rej) => {
            const tx = db.transaction(STORE_NAME, 'readwrite');
            const data = { hash, blob, prompt, config, timestamp: Date.now(), message_id: msgId, seed: actualSeed };
            const req = tx.objectStore(STORE_NAME).put(data);
            req.onsuccess = () => res(); req.onerror = () => rej(req.error);
        });
    }
    async function getImageFromDB(hash) {
        const db = await dbPromise;
        return new Promise((res, rej) => {
            if (!db.objectStoreNames.contains(STORE_NAME)) return res(null);
            const req = db.transaction(STORE_NAME, 'readonly').objectStore(STORE_NAME).get(hash);
            req.onsuccess = () => res(req.result ? req.result.blob : null); req.onerror = () => rej(req.error);
        });
    }
    async function getAllImagesFromDB() {
        const db = await dbPromise;
        return new Promise((res, rej) => {
            if (!db.objectStoreNames.contains(STORE_NAME)) return res([]);
            const req = db.transaction(STORE_NAME, 'readonly').objectStore(STORE_NAME).getAll();
            req.onsuccess = () => res(req.result || []); req.onerror = () => rej(req.error);
        });
    }
    async function deleteImageFromDB(hash) {
        const db = await dbPromise;
        return new Promise((res, rej) => {
            const req = db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).delete(hash);
            req.onsuccess = () => res(); req.onerror = () => rej(req.error);
        });
    }
    async function getBlobUrl(hash) {
        if (BlobUrlCache[hash]) return BlobUrlCache[hash];
        const blob = await getImageFromDB(hash);
        if (blob) { const url = hostWindow.URL.createObjectURL(blob); BlobUrlCache[hash] = url; return url; }
        return null;
    }
    let trackers = {};
    let zIndexCounter = 20000;
    function getOverlayLayer() {
        const chatContainer = hostWindow.document.getElementById('chat');
        if (!chatContainer) return null;
        let layer = hostWindow.document.getElementById('ldsd-phantom-layer');
        if (!layer) {
            if (hostWindow.getComputedStyle(chatContainer).position === 'static') chatContainer.style.position = 'relative';
            layer = hostWindow.document.createElement('div');
            layer.id = 'ldsd-phantom-layer';
            layer.style.cssText = 'position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 99999;';
            chatContainer.appendChild(layer);
        }
        return { layer, chatContainer };
    }
    function fastFindTextRect($container, targetText) {
        if (!$container || $container.length === 0 || !targetText) return null;
        const walker = hostWindow.document.createTreeWalker($container[0], NodeFilter.SHOW_TEXT, null, false);
        let node;
        while ((node = walker.nextNode())) {
            const idx = node.nodeValue.indexOf(targetText);
            if (idx !== -1) { const range = hostWindow.document.createRange(); range.setStart(node, idx); range.setEnd(node, idx + targetText.length); return range.getBoundingClientRect(); }
        }
        return null;
    }
    function transformFloaterToImage(tracker, imgUrl) {
        tracker.elem.innerHTML = '<img src="' + imgUrl + '" draggable="false" style="width:100%; border-radius:12px; display:block; object-fit:contain; box-shadow: 0 4px 15px rgba(0,0,0,0.1);" />';
        tracker.elem.style.padding = '0px'; tracker.elem.style.border = 'none'; tracker.elem.style.background = 'transparent'; tracker.elem.style.boxShadow = 'none'; tracker.elem.style.pointerEvents = 'none';
    }
    function createPhantomFloater(hash, prompt, msgId) {
        const { layer } = getOverlayLayer();
        if (!layer) return null;
        const panel = hostWindow.document.createElement('div');
        panel.id = 'ldsd-inst-' + hash;
        panel.style.cssText = 'position: absolute !important; width: 90% !important; max-width: 360px !important; background: rgba(128, 128, 128, 0.1) !important; backdrop-filter: blur(2px) !important; border: none !important; z-index: ' + zIndexCounter + ' !important; padding: 8px !important; border-radius: 8px !important; font-family: system-ui, sans-serif !important; display: flex !important; flex-direction: column !important; color: #94a3b8 !important; pointer-events: none !important; opacity: 0; transition: opacity 0.3s ease;';
        panel.innerHTML = '<div style="font-weight:normal; color:#94a3b8; padding-bottom:4px; font-size:12px; display:flex; align-items:center; gap:6px; opacity:0.7;"><div style="width:6px; height:6px; background:#94a3b8; border-radius:50%; animation: ldpulse 1s infinite alternate;"></div><span>构思画面中...</span></div><div style="font-size:12px; line-height:1.4; color:#94a3b8; overflow-y:auto; max-height:80px; flex:1; position:relative; opacity:0.6;">' + prompt + '</div><style>@keyframes ldpulse { from { opacity: 0.2; } to { opacity: 1; } }</style>';
        layer.appendChild(panel);
        return { elem: panel, prompt: prompt, msgId: msgId, isTracking: true };
    }
    function updateAllTrackingPositions() {
        const { layer } = getOverlayLayer(); if (!layer) return;
        const layerRect = layer.getBoundingClientRect();
        Object.keys(trackers).forEach(hash => {
            const state = trackers[hash]; if (!state.isTracking) return;
            const $mes = retrieveDisplayedMessage(state.msgId); if (!$mes || $mes.length === 0) return;
            const textRect = fastFindTextRect($mes, state.prompt);
            if (textRect && textRect.height > 0) {
                state.elem.style.opacity = '1'; state.elem.style.top = (textRect.bottom - layerRect.top + 6) + 'px';
                const panelWidth = state.elem.offsetWidth || 300; state.elem.style.left = Math.max(0, (layerRect.width - panelWidth) / 2) + 'px';
            } else { state.elem.style.opacity = '0'; }
        });
    }
    function applyImgStyle($elem) {
        $elem.css({ 'max-width': '100%', 'border-radius': '12px', 'box-shadow': '0 4px 15px rgba(0,0,0,0.1)', 'border': 'none', 'margin-top': '12px', 'object-fit': 'contain', 'display': 'block', 'background': 'transparent', 'padding': '0' });
    }
    function hydrateDisplayedMessageSync(msgId) {
        const $mes = retrieveDisplayedMessage(msgId); if (!$mes || $mes.length === 0) return;
        $mes.find('img[data-ldsd-hash]').each(function () {
            const hash = $(this).attr('data-ldsd-hash'); const currentSrc = $(this).attr('src');
            if (!currentSrc || !currentSrc.startsWith('blob:')) {
                if (BlobUrlCache[hash]) { $(this).attr('src', BlobUrlCache[hash]); applyImgStyle($(this)); }
                else { getBlobUrl(hash).then(url => { if (url) { $(this).attr('src', url); applyImgStyle($(this)); } }); }
            }
        });
    }
    function runHydrationPulse(msgId) {
        const pulse = () => { try { if (msgId === 'all') { const lastId = getLastMessageId(); const start = Math.max(0, lastId - 40); const msgs = getChatMessages(start + '-' + lastId); if (msgs) for (let m of msgs) hydrateDisplayedMessageSync(m.message_id); } else { hydrateDisplayedMessageSync(msgId); } } catch (e) {} };
        pulse(); setTimeout(pulse, 100); setTimeout(pulse, 300); setTimeout(pulse, 800);
    }
    async function processAndHydrateMessage(msgId) {
        const msgs = getChatMessages(msgId); if (!msgs || !msgs[0]) return;
        let isChanged = false, newMessage = msgs[0].message;
        const chatVars = getVariables({ type: 'chat' });
        newMessage = newMessage.replace(/<local_img>([\s\S]*?)<\/local_img>/gi, (match, p1) => {
            const prompt = p1.trim(); const hash = hashPrompt(prompt);
            if (chatVars['LDSD_STATE_' + hash] === 'DONE') {
                isChanged = true;
                if (trackers[hash]) { trackers[hash].elem.remove(); delete trackers[hash]; }
                return '\n\n<img data-ldsd-hash="' + hash + '" src="" alt="LD Image" />\n\n';
            }
            return match;
        });
        if (isChanged) { try { await setChatMessages([{ message_id: msgId, message: newMessage }]); } catch (e) {} }
        runHydrationPulse(msgId);
    }
    const generateQueue = [];
    function base64ToBlob(base64, contentType) { return fetch('data:' + contentType + ';base64,' + base64).then(res => res.blob()); }
    async function executeGeneration(prompt, modelId) {
        const config = getConfig();
        const targetModelId = modelId || config.model_id;
        if (!targetModelId) throw new Error('请先在设置中选择模型');
        let scheduler = config.scheduler_base;
        if (config.use_karras && scheduler !== 'lcm') scheduler = scheduler + '_karras';
        const payload = {
            prompt: prompt, negative_prompt: config.negative_prompt, model_id: targetModelId,
            steps: Number(config.steps), cfg: Number(config.cfg),
            width: Number(config.resolution), height: Number(config.resolution),
            scheduler: scheduler, denoise_strength: Number(config.denoise_strength) / 100.0,
            mode: "txt2img", show_preview: false, preview_stride: 2, speed_mode: "balanced",
            seed: config.seed !== "" && !isNaN(Number(config.seed)) ? Number(config.seed) : Math.floor(Math.random() * 2147483647)
        };
        const response = await fetch(getApiBase() + '/api/generate', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'text/event-stream' }, body: JSON.stringify(payload) });
        if (!response.ok) throw new Error('API 异常: ' + response.status);
        const reader = response.body.getReader();
        const decoder = new TextDecoder('utf-8');
        let buffer = '', finalImage = null, actualSeedUsed = null;
        while (true) {
            const { done, value } = await reader.read(); if (done) break;
            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n'); buffer = lines.pop();
            for (const line of lines) {
                if (line.startsWith('data: ')) {
                    try { const str = line.substring(6).trim(); if (!str) continue; const evt = JSON.parse(str);
                        if (evt.type === 'progress' && manualProgressCallback) manualProgressCallback(evt.step, evt.total_steps, false);
                        else if (evt.type === 'complete') { finalImage = evt; actualSeedUsed = evt.seed; }
                        else if (evt.type === 'error') throw new Error(evt.message);
                    } catch (e) {}
                }
            }
        }
        if (!finalImage) throw new Error('API 未返回完整数据');
        let blob;
        if (finalImage.image) {
            if (finalImage.image.startsWith('data:')) blob = await base64ToBlob(finalImage.image);
            else blob = await base64ToBlob(finalImage.image, 'image/' + (finalImage.format || 'jpeg'));
        } else { throw new Error('未找到图片数据'); }
        return { blob, config, actualSeedUsed };
    }
    async function processQueue() {
        if (isProcessing || generateQueue.length === 0) return;
        isProcessing = true;
        const task = generateQueue.shift();
        try {
            const result = await executeGeneration(task.prompt, task.modelId);
            await saveImageToDB(task.hash, result.blob, task.prompt, result.config, task.msgId, result.actualSeedUsed);
            const cachedUrl = hostWindow.URL.createObjectURL(result.blob);
            BlobUrlCache[task.hash] = cachedUrl;
            if (task.msgId !== 'Manual') {
                insertOrAssignVariables({ ['LDSD_STATE_' + task.hash]: 'DONE' }, { type: 'chat' });
                if (builtin.duringGenerating() && msgIdMatchLast(task.msgId)) {
                    if (trackers[task.hash]) transformFloaterToImage(trackers[task.hash], cachedUrl);
                } else { await processAndHydrateMessage(task.msgId); }
            }
        } catch (e) {
            console.error('[LDSD] Generation error:', e);
            if (task.msgId !== 'Manual') {
                insertOrAssignVariables({ ['LDSD_STATE_' + task.hash]: 'ERROR' }, { type: 'chat' });
                if (trackers[task.hash]) { trackers[task.hash].elem.remove(); delete trackers[task.hash]; }
            }
        } finally {
            if (task.msgId === 'Manual' && typeof manualProgressCallback === 'function') manualProgressCallback(100, 100, true);
            setTimeout(() => { isProcessing = false; processQueue(); }, 200);
        }
    }
    function msgIdMatchLast(id) { const msgs = getChatMessages(-1); return msgs && msgs.length > 0 && msgs[0].message_id === id; }
    function enqueueGeneration(prompt, msgId, modelId) {
        let taskHash = hashPrompt(prompt);
        if (msgId === 'Manual') { taskHash = hashPrompt(prompt + '_' + Date.now()); }
        else {
            if (generateQueue.find(t => t.hash === taskHash)) return;
            const currentVars = getVariables({ type: 'chat' });
            if (currentVars && currentVars['LDSD_STATE_' + taskHash]) return;
            insertOrAssignVariables({ ['LDSD_STATE_' + taskHash]: 'PENDING' }, { type: 'chat' });
        }
        generateQueue.push({ hash: taskHash, prompt, msgId, modelId });
        processQueue();
    }
    const extractRegex = /<local_img>([\s\S]*?)<\/local_img>/gi;
    eventOn(tavern_events.STREAM_TOKEN_RECEIVED, () => {
        const msgs = getChatMessages(-1); if (!msgs || msgs.length === 0) return;
        const currentMsgId = msgs[0].message_id; const content = msgs[0].message; let match; extractRegex.lastIndex = 0;
        while ((match = extractRegex.exec(content)) !== null) {
            const pt = match[1].trim(); if (pt.length === 0) continue;
            const hash = hashPrompt(pt); enqueueGeneration(pt, currentMsgId, getConfig().model_id);
            const chatVars = getVariables({ type: 'chat' });
            if (!trackers[hash]) {
                const floater = createPhantomFloater(hash, pt, currentMsgId);
                if (chatVars['LDSD_STATE_' + hash] === 'DONE' && BlobUrlCache[hash]) transformFloaterToImage(floater, BlobUrlCache[hash]);
                if (floater) trackers[hash] = floater;
            }
        }
        updateAllTrackingPositions();
    });
    eventOn(tavern_events.GENERATION_ENDED, async () => {
        const msgs = getChatMessages(-1); if (msgs && msgs[0]) await processAndHydrateMessage(msgs[0].message_id);
        clearOldImages();
    });
    eventOn(tavern_events.CHAT_CHANGED, () => { Object.values(trackers).forEach(i => i.elem.remove()); trackers = {}; runHydrationPulse('all'); });
    eventOn(tavern_events.MESSAGE_UPDATED, (id) => { runHydrationPulse(id); });
    eventOn(tavern_events.MESSAGE_SWIPED, (id) => { Object.values(trackers).forEach(i => i.elem.remove()); trackers = {}; runHydrationPulse(id); });
    async function clearOldImages() {
        const conf = getConfig(); if (!conf.auto_clear) return;
        const limit = getLastMessageId() - Number(conf.keep_floors); if (limit < 0) return;
        try { const allImgs = await getAllImagesFromDB(); for (const img of allImgs) { if (img.message_id !== 'Manual' && typeof img.message_id === 'number' && img.message_id < limit) { await deleteImageFromDB(img.hash); deleteVariable('LDSD_STATE_' + img.hash, { type: 'chat' }); if (BlobUrlCache[img.hash]) { hostWindow.URL.revokeObjectURL(BlobUrlCache[img.hash]); delete BlobUrlCache[img.hash]; } } } } catch (e) {}
    }
    let floatingBall = null, uiContainer = null, isMultiSelect = false, selectedHashes = new Set();
    function syncFabState() { const conf = getConfig(); if (conf.fab_enabled) { if (!floatingBall) createFloatingBall(); floatingBall.style.display = 'flex'; } else { if (floatingBall) floatingBall.style.display = 'none'; } }
    function createFloatingBall() {
        const STORAGE_KEY = 'ldsd-fab-pos'; const FAB_SIZE = 44;
        let hasMoved = false, dragStart = { x: 0, y: 0 }, dragBase = { x: 0, y: 0 };
        function clampPos(x, y) { return { x: Math.max(10, Math.min(x, hostWindow.innerWidth - FAB_SIZE - 10)), y: Math.max(10, Math.min(y, hostWindow.innerHeight - FAB_SIZE - 10)) }; }
        floatingBall = hostWindow.document.createElement('div'); floatingBall.innerHTML = '🎨';
        const raw = hostWindow.localStorage.getItem(STORAGE_KEY);
        const pos = raw ? clampPos(JSON.parse(raw).x, JSON.parse(raw).y) : { x: hostWindow.innerWidth - 60, y: hostWindow.innerHeight - 150 };
        floatingBall.style.cssText = 'position:fixed!important; top:' + pos.y + 'px!important; left:' + pos.x + 'px!important; width:' + FAB_SIZE + 'px!important; height:' + FAB_SIZE + 'px!important; line-height:' + FAB_SIZE + 'px!important; border-radius:50%!important; background:rgba(15,23,42,0.88)!important; border:1px solid rgba(255,255,255,0.1)!important; backdrop-filter:blur(8px)!important; cursor:grab!important; display:flex!important; align-items:center!important; justify-content:center!important; box-shadow:0 4px 16px rgba(0,0,0,0.3)!important; color:white!important; z-index:999998!important; user-select:none!important; touch-action:none!important; font-size:20px!important;';
        floatingBall.onpointerdown = (e) => {
            if (e.button !== 0) return; e.preventDefault(); hasMoved = false;
            dragStart = { x: e.clientX, y: e.clientY }; dragBase = { x: floatingBall.getBoundingClientRect().left, y: floatingBall.getBoundingClientRect().top };
            floatingBall.style.cursor = 'grabbing';
            const move = (em) => { const dx = em.clientX - dragStart.x, dy = em.clientY - dragStart.y; if (Math.abs(dx) > 3 || Math.abs(dy) > 3) { hasMoved = true; const np = clampPos(dragBase.x + dx, dragBase.y + dy); floatingBall.style.left = np.x + 'px'; floatingBall.style.top = np.y + 'px'; } };
            const up = () => { hostWindow.removeEventListener('pointermove', move); hostWindow.removeEventListener('pointerup', up); floatingBall.style.cursor = 'grab'; setTimeout(() => hasMoved = false, 100); hostWindow.localStorage.setItem(STORAGE_KEY, JSON.stringify({ x: floatingBall.getBoundingClientRect().left, y: floatingBall.getBoundingClientRect().top })); };
            hostWindow.addEventListener('pointermove', move); hostWindow.addEventListener('pointerup', up);
        };
        floatingBall.onclick = () => { if (!hasMoved && typeof createUI === 'function') createUI(); };
        hostWindow.document.body.appendChild(floatingBall);
    }
    function applyThemeToUI(theme) {
        if (!uiContainer) return;
        if (theme === 'light') { uiContainer.style.setProperty('--ld-bg', '#f1f5f9'); uiContainer.style.setProperty('--ld-card', '#ffffff'); uiContainer.style.setProperty('--ld-border', '#cbd5e1'); uiContainer.style.setProperty('--ld-text', '#0f172a'); uiContainer.style.setProperty('--ld-text-dim', '#64748b'); uiContainer.style.setProperty('--ld-input-bg', '#f8fafc'); }
        else { uiContainer.style.setProperty('--ld-bg', '#0f172a'); uiContainer.style.setProperty('--ld-card', '#1e293b'); uiContainer.style.setProperty('--ld-border', '#334155'); uiContainer.style.setProperty('--ld-text', '#f8fafc'); uiContainer.style.setProperty('--ld-text-dim', '#94a3b8'); uiContainer.style.setProperty('--ld-input-bg', '#0f172a'); }
    }
    async function cleanResidualVars() {
        const allImgs = await getAllImagesFromDB(); const validSet = new Set(allImgs.map(i => i.hash));
        generateQueue.forEach(t => validSet.add(t.hash)); const vars = getVariables({ type: 'chat' }); let cleans = 0;
        for (const key in vars) { if (key.startsWith('LDSD_STATE_')) { const pureHash = key.replace('LDSD_STATE_', ''); if (!validSet.has(pureHash)) { deleteVariable(key, { type: 'chat' }); cleans++; } } }
        alert('变量深度净化结束！清除 ' + cleans + ' 个残余。');
    }
    function createUI() {
        if (uiContainer) { uiContainer.style.display = 'flex'; applyThemeToUI(getConfig().theme); if (uiContainer.querySelector('#ldsd-tab-gallery').style.display === 'flex') renderGallery(); checkApiStatus(); return; }
        const doc = hostWindow.document; uiContainer = doc.createElement('div');
        uiContainer.style.cssText = 'position:fixed; top:0; left:0; width:100vw; height:100vh; background:rgba(0,0,0,0.5); z-index:999999; display:flex; justify-content:center; align-items:center; backdrop-filter:blur(3px); font-family: system-ui, sans-serif; font-size: 14px;';
        uiContainer.innerHTML = '<div style="background:var(--ld-card); border:1px solid var(--ld-border); color:var(--ld-text); border-radius:12px; width:90%; max-width:700px; height:85vh; display:flex; flex-direction:column; box-shadow:0 12px 40px rgba(0,0,0,0.3); overflow:hidden;">' +
            '<div style="background:var(--ld-bg); padding:16px; display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--ld-border);"><h2 style="margin:0; font-size:16px; display:flex; align-items:center; gap:8px;"><div id="ldsd-ui-dot" style="width:10px; height:10px; border-radius:50%; background:' + (isApiOnline ? '#22c55e' : '#ef4444') + ';"></div>LocalDream-SD v1.1</h2><button id="ldsd-ui-close" style="background:transparent; border:none; color:var(--ld-text-dim); cursor:pointer; font-size:24px; line-height:1;">x</button></div>' +
            '<div style="display:flex; border-bottom:1px solid var(--ld-border); background:var(--ld-card);"><button class="ldsd-tab-btn" data-target="ldsd-tab-config" style="flex:1; padding:12px; background:transparent; border:none; color:var(--ld-text); font-weight:bold; border-bottom:2px solid #3b82f6;">连接设置</button><button class="ldsd-tab-btn" data-target="ldsd-tab-gen" style="flex:1; padding:12px; background:transparent; border:none; color:var(--ld-text-dim); font-weight:bold; border-bottom:2px solid transparent;">生成参数</button><button class="ldsd-tab-btn" data-target="ldsd-tab-gallery" style="flex:1; padding:12px; background:transparent; border:none; color:var(--ld-text-dim); font-weight:bold; border-bottom:2px solid transparent;">图库</button></div>' +
